import numpy as np
from scipy.optimize import linear_sum_assignment


class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"])
        b = np.asarray(problem["target_weights"])
        M = np.asarray(problem["cost_matrix"])
        n, m = M.shape
        # Benchmark instances have equal, uniform marginals.  The transport LP
        # is then precisely a (scaled) linear assignment problem.
        if n == m and np.all(a == a[0]) and np.all(b == b[0]):
            rows, cols = linear_sum_assignment(M)
            G = np.zeros((n, m), dtype=np.float64)
            G[rows, cols] = a[rows]
            return {"transport_plan": G}

        # Retain the general transportation solver for non-uniform inputs.
        import ot
        return {"transport_plan": ot.lp.emd(a, b, np.ascontiguousarray(M, dtype=np.float64),
                                             check_marginals=False)}
