#include <stdlib.h>
#include <math.h>
// epsilon scaling auction for minimum assignment
void solve(int n, const double *c, int *assign) {
 double *price=calloc(n,sizeof(double));
 int *owner=malloc(n*sizeof(int)); int *q=malloc(n*sizeof(int));
 double mx=0; for(int z=0;z<n*n;z++) if(c[z]>mx)mx=c[z];
 double eps=mx/4.0;
 for(int phase=0; phase<22; phase++,eps*=0.25) {
   for(int j=0;j<n;j++) owner[j]=-1;
   int head=0,tail=n; for(int i=0;i<n;i++){assign[i]=-1;q[i]=i;}
   while(head<tail) {
     int i=q[head++]; const double *row=c+(size_t)i*n;
     int bj=0; double best=-row[0]-price[0], second=-INFINITY;
     for(int j=1;j<n;j++) { double v=-row[j]-price[j];
       if(v>best){second=best;best=v;bj=j;} else if(v>second)second=v;
     }
     price[bj] += best-second+eps;
     int old=owner[bj]; owner[bj]=i; assign[i]=bj;
     if(old>=0){assign[old]=-1;q[tail++]=old;}
   }
 }
 free(price);free(owner);free(q);
}
